import numpy as np,pandas as pd
from scipy.signal import savgol_filter
from scipy.optimize import curve_fit
for n in ['Au','Cu']:
    d=pd.read_csv(f'spectrum_{n}.csv');x=d.shift_cm1.values;y=d.intensity.values
    # noise from high-pass of 2900-3500 region
    m=(x>2900)&(x<3500); p=np.polyfit(x[m],y[m],3); print(n,'noise sd',np.std(y[m]-np.polyval(p,x[m])))
    def L(x,h,c,w,a,b): return h/(1+((x-c)/(w/2))**2)+a+b*(x-1450)
    for lo,hi,c0 in [(1250,1450,1344),(1500,1700,1580)]:
        m=(x>lo)&(x<hi)
        try:
            p,cv=curve_fit(L,x[m],y[m],p0=[20,c0,30,y[m].mean(),0],maxfev=20000)
            print(n,c0,'h=%.1f+-%.1f c=%.1f w=%.1f'%(p[0],np.sqrt(cv[0,0]),p[1],p[2]))
        except Exception as e: print(n,c0,e)
"

